<?php
declare(strict_types=1); namespace Box\Mod\Quizontalverification\Controller;
use FOSSBilling\InformationException;
class Client implements \FOSSBilling\InjectionAwareInterface { protected ?\Pimple\Container $di=null; public function setDi(\Pimple\Container $d):void{$this->di=$d;}public function getDi():?\Pimple\Container{return $this->di;} public function register(\Box_App &$app):void{$app->get('/verify-email/:hash','confirm',['hash'=>'[a-z0-9]+'],static::class);$app->post('/verify-email/resend','resend',[],static::class);} public function confirm(\Box_App $app,$hash):string { $ok=true;$error='';try{$this->di['mod_service']('client')->approveClientEmailByHash((string)$hash);}catch(\Throwable $e){$ok=false;$error='This verification link is invalid or has already been used.';}return $app->render('mod_quizontalverification_result',['verified'=>$ok,'error'=>$error]);} public function resend(\Box_App $app){$this->di['is_client_logged'];try{$wait=$this->di['mod_service']('quizontalverification')->resend($this->di['loggedin_client']);return $app->redirect('client/profile?verification_resent=1&resend_after='.$wait);}catch(InformationException $e){return $app->redirect('client/profile?verification_error='.rawurlencode($e->getMessage()));}} }
